#[cfg(any(target_arch = "x86", target_arch = "x86_64"))]
#[target_feature(enable = "avx2")]
unsafe fn estimate4_avx2(n: [f64; 4], d: [f64; 4]) -> [f64; 4] {
    let left = _mm256_setr_pd(n[0], n[1], n[2], n[3]);
    let right = _mm256_setr_pd(d[0], d[1], d[2], d[3]);
    // 初期値だけf32。補正は元のdを用いる。精度不足は呼出し側certificateで拒否。
    let initial = _mm_rcp_ps(_mm256_cvtpd_ps(right));
    let mut reciprocal = _mm256_cvtps_pd(initial);
    let two = _mm256_set1_pd(2.0);
    reciprocal = _mm256_mul_pd(reciprocal, _mm256_sub_pd(two, _mm256_mul_pd(right, reciprocal)));
    reciprocal = _mm256_mul_pd(reciprocal, _mm256_sub_pd(two, _mm256_mul_pd(right, reciprocal)));
    let result = _mm256_mul_pd(left, reciprocal);
    let mut output = [0.0; 4];
    // 正確に4doubleの領域。丸めた推定からの商は必ずchecked整数余りで検算する。
    unsafe { _mm256_storeu_pd(output.as_mut_ptr(), result); }
    output
}
